<?php require_once __DIR__.'/../config/auth.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$s=db()->prepare('INSERT INTO usuarios(nome,email,senha,tipo,telefone,ra,status) VALUES(?,?,?,?,?,?,"ativo")');$s->execute([trim($_POST['nome']),trim($_POST['email']),password_hash($_POST['senha'],PASSWORD_DEFAULT),$_POST['tipo'],trim($_POST['telefone']),trim($_POST['ra'])]);flash('success','Gestor cadastrado.');redirect('admin/gestores.php');}catch(PDOException $e){$error='E-mail ou RA já cadastrado.';}}$users=db()->query("SELECT * FROM usuarios WHERE tipo IN ('administrador','gestor','bibliotecario') ORDER BY nome")->fetchAll();$pageTitle='Gestores';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><div class="dashboard-cards"><form class="panel" method="post" style="margin:0;grid-column:span 1"><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?=csrf_field()?><h2>Novo gestor</h2><div class="form-group"><label>Nome</label><input required name="nome"></div><div class="form-group"><label>E-mail</label><input required type="email" name="email"></div><div class="form-group"><label>Senha</label><input required minlength="8" type="password" name="senha"></div><div class="form-group"><label>Telefone</label><input name="telefone"></div><div class="form-group"><label>RA / matrícula</label><input name="ra"></div><div class="form-group"><label>Cargo</label><select name="tipo"><option value="gestor">Gestor</option><option value="bibliotecario">Bibliotecário</option><option value="administrador">Administrador</option></select></div><button class="btn">Cadastrar</button></form><section class="panel" style="margin:0;grid-column:span 2"><h2>Equipe cadastrada</h2><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Cargo</th><th>Status</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['nome'])?></td><td><?=e($u['email'])?></td><td><?=e(ucfirst($u['tipo']))?></td><td><span class="badge"><?=e($u['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../includes/dashboard-footer.php';?>
